$profile = { email: "", updates: false }

$app(Card([
  FormControl("Email", Input("email", { value: $profile.email })),
  Switch("updates", { label: "Send me product updates", value: $profile.updates }),
  Text(`We will write to ${$profile.email}`)
]))

function Counter(label) {
  $n = 0
  return Card([
    Text(`${label}: ${$n}`),
    Button("+1", { onClick: () => $n += 1 })
  ])
}

