  return Card([
    Text(`${label}: ${$n}`, { variant: "large-heavy" }),
    Button("+1", { onClick: () => $n += 1, variant: "primary" })
  ])
}

$app(Row([Counter("Left"), Counter("Right")], { gap: "md" }))

